import "./TimeList.css";

export type TimeState = "past" | "next" | "later";

export interface TimeItem {
  name: string;
  time: string;
  state: TimeState;
}

export interface TimeListProps {
  items: readonly TimeItem[];
}

const STATE_LABEL: Record<TimeState, string> = {
  past: "passed",
  next: "next",
  later: "later",
};

export function TimeList({ items }: TimeListProps) {
  return (
    <ol
      className="time-list"
      tabIndex={0}
      aria-label="Times through the day"
    >
      {items.map((item) => (
        <li
          key={`${item.name}-${item.time}`}
          className={`time-list__item time-list__item--${item.state}`}
          aria-current={item.state === "next" ? "step" : undefined}
        >
          <span className="time-list__marker" aria-hidden="true" />
          <span className="time-list__name">{item.name}</span>
          <time className="time-list__time">{item.time}</time>
          <span className="sr-only">: {STATE_LABEL[item.state]}</span>
        </li>
      ))}
    </ol>
  );
}
```

**TimeList.css**

```css
.time-list {
  list-style: none;
  margin: 0;
  padding: 0;
  font: inherit;
  color: var(--ink);
  border-top: 1px solid var(--hair);
}

.time-list:focus-visible {
  border-radius: 0.5em;
}

.time-list__item {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 0.75em;
  padding: clamp(0.6rem, 1.2vh, 0.9rem) clamp(0.5rem, 1vw, 0.9rem);
  border-bottom: 1px solid var(--hair);
  border-radius: 0.5em;
  font-size: clamp(1rem, 1.6vw, 1.5rem);
  transition: background-color 200ms ease, color 200ms ease;
}

.time-list__marker {
  box-sizing: border-box;
  width: 0.75em;
  height: 0.75em;
  border-radius: 999px;
  border: 2px solid var(--muted);
  background: transparent;
}

.time-list__name {
  min-width: 0;
  overflow-wrap: anywhere;
}

.time-list__time {
  justify-self: end;
  font-variant-numeric: tabular-nums;
  color: var(--ink);
}

/* Past: quieter, filled marker showing it is done. Colour is lowered by token, not opacity. */
.time-list__item--past {
  color: var(--muted);
}

.time-list__item--past .time-list__marker {
  border-color: var(--myelin);
  background: var(--myelin);
}

.time-list__item--past .time-list__time {
  color: var(--muted);
}

/* Next: highlighted row and a cresyl marker. */
.time-list__item--next {
  background: var(--cresyl-wash);
  font-weight: 600;
}

.time-list__item--next .time-list__marker {
  border-color: var(--cresyl);
  background: var(--cresyl);
}

/* Later: the default look, with a hollow marker. */
.time-list__item--later .time-list__marker {
  border-color: var(--muted);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

:root[data-motion="reduce"] .time-list__item {
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .time-list__item {
    transition: none;
  }
}
```

